// The person the player is talking to
struct Speaker {
  std::string id;  // world db npc.id
  std::string name;  // the name the player sees
  bool operator==(const Speaker&) const = default;
};

// One run of display text; a run with a topic is a hyperlinked keyword span
struct TextRun {
  std::string text;  // the run's text, as the record has it
  std::optional<std::string> topic;  // the topic id the keyword asks about (world db topic.id)
  bool operator==(const TextRun&) const = default;
};

// One block of the scrolling conversation, oldest first
struct DialogueEntry {
  DialogueEntryKind kind{};  // what put an entry in the window
  std::optional<std::string> heading;  // the topic label asked, shown above an answer
  std::vector<TextRun> runs;  // the text, split at keyword spans
  bool operator==(const DialogueEntry&) const = default;
};

// One entry of the topic list
struct TopicItem {
  std::string id;  // world db topic.id
  std::string label;  // the label the player clicks
  bool operator==(const TopicItem&) const = default;
};

// Disposition as Morrowind shows it
struct Disposition {
  std::int64_t value = 0;  // 0..100
  DispositionBand band{};  // the band the record's variant text keys on (core_disposition_band)
  bool operator==(const Disposition&) const = default;
};

// One persuasion action (admire, intimidate, taunt, bribe and our own)
struct PersuasionOption {
  std::string id;  // the action id; the set is ArgoniaCore's (2.5)
  std::string label;  // the button text
  bool enabled = false;  // false when the action cannot be taken now
  std::optional<std::int64_t> cost;  // gold it spends (a bribe)
  bool operator==(const PersuasionOption&) const = default;
};

// The persuasion button and its actions
struct Persuasion {
  bool available = false;  // whether the button shows
  std::vector<PersuasionOption> options;  // One persuasion action (admire, intimidate, taunt, bribe and our own)
  bool operator==(const Persuasion&) const = default;
};

// The whole dialogue window, sent on open and after every change
struct DialogueState {
  Speaker speaker;  // The person the player is talking to
  std::vector<DialogueEntry> entries;  // the conversation so far, oldest first
  std::vector<TopicItem> topics;  // the topics this person can be asked, in display order
  Disposition disposition;  // Disposition as Morrowind shows it
  Persuasion persuasion;  // The persuasion button and its actions
  std::vector<ServiceKind> services;  // the service buttons, in display order (barter: a merchant's vendor faction)
  bool can_leave = false;  // whether Goodbye is offered (a forced conversation hides it)
  bool operator==(const DialogueState&) const = default;
};

// A topic in the list was chosen
struct DialogueTopic {
  std::string topic;  // world db topic.id
  bool operator==(const DialogueTopic&) const = default;
};

// A hyperlinked keyword in the text was clicked
struct DialogueKeyword {
  std::string topic;  // world db topic.id the run carried
  bool operator==(const DialogueKeyword&) const = default;
};

// A persuasion action was taken
struct DialoguePersuade {
  std::string option;  // PersuasionOption.id
  bool operator==(const DialoguePersuade&) const = default;
};

// Goodbye was chosen
struct DialogueGoodbye {
  bool operator==(const DialogueGoodbye&) const = default;
};

// A service button was chosen: Barter opens Skyrim's BarterMenu (Wind UI draws it), then the conversation returns
struct DialogueService {
  ServiceKind service{};  // a service the speaker offers beside the topics (Morrowind's buttons)
  bool operator==(const DialogueService&) const = default;
};

// A date on the game calendar, with ArgoniaCore's rendering of it
struct GameDate {
  std::int64_t year = 0;  // the era year
  std::int64_t month = 0;  // 1-based month
  std::int64_t day = 0;  // 1-based day of the month
  double hour = 0;  // hour of the day
  std::string text;  // the date as the player reads it; views never format game dates
  bool operator==(const GameDate&) const = default;
};

// One quest of a ribbon's list
struct QuestIndexItem {
  std::string id;  // world db quest.id
  std::string name;  // the quest's name
  QuestStatus status{};  // a quest's standing in the index
  GameDate started;  // A date on the game calendar, with ArgoniaCore's rendering of it
  GameDate last;  // the date of its latest entry
  bool operator==(const QuestIndexItem&) const = default;
};

// The quests of one questline or one place, most recently written first
struct QuestGroup {
  std::string label;  // the questline's or the place's name (the quest records)
  QuestGroupKind kind{};  // what a group of quests is named for (quest_line.group local: the place)
  std::vector<QuestIndexItem> quests;  // One quest of a ribbon's list
  bool operator==(const QuestGroup&) const = default;
};

// One dated entry of the log
struct JournalEntry {
  std::string quest;  // world db quest.id
  std::string quest_name;  // the quest's name as the book heads it
  GameDate date;  // A date on the game calendar, with ArgoniaCore's rendering of it
  JournalEntryKind kind{};  // what the entry records
  std::vector<TextRun> runs;  // the entry text, split at keyword spans (links join in 2.12)
  bool operator==(const JournalEntry&) const = default;
};

// The quest the book is open at: its latest direction, then its entries
struct OpenQuest {
  std::string id;  // world db quest.id
  std::string name;  // the quest's name
  QuestStatus status{};  // a quest's standing in the index
  std::string group;  // the questline or place it is listed under
  std::optional<std::string> directions;  // where to go next in words, never a marker (the latest stage's directions)
  std::vector<JournalEntry> entries;  // its entries, newest first
  bool operator==(const OpenQuest&) const = default;
};

// The open journal at one ribbon
struct JournalState {
  JournalTab tab{};  // the ribbon the book is open at
  std::int64_t page = 0;  // 0-based page of the All entries diary
  std::int64_t page_count = 0;  // pages of the diary
  std::optional<std::string> search;  // the typed search the tab is narrowed by, as typed
  std::vector<QuestGroup> groups;  // Current or Finished: the quests matching the search, by group
  std::optional<OpenQuest> quest;  // the quest opened from Current or Finished
  std::vector<JournalEntry> entries;  // All entries: this page of the diary, oldest first
  std::int64_t matches = 0;  // entries (All entries) or quests (Current, Finished) the search matched
  bool operator==(const JournalState&) const = default;
};

// A ribbon chosen, a page turned, a quest opened or the search typed
struct JournalPage {
  JournalTab tab{};  // the ribbon the book is open at
  std::int64_t page = 0;  // 0-based diary page asked for
  std::optional<std::string> quest;  // open this quest id (Current or Finished)
  std::optional<std::string> search;  // narrow the tab to entries and quests containing these words
  bool operator==(const JournalPage&) const = default;
};

// One bar; its drawn length grows with max
struct Bar {
  BarKind kind{};  // a bar of the HUD
  double current = 0;  // the current value
  double max = 0;  // the maximum, which sets the bar's length
  bool shown = false;  // false hides the bar (breath above water, climb off a wall)
  bool operator==(const Bar&) const = default;
};

// The sneak eye
struct Sneak {
  bool sneaking = false;  // whether the eye shows
  double eye = 0;  // how open the eye is: 0 unseen, 1 detected
  bool operator==(const Sneak&) const = default;
};

// One entry of the effect stack
struct Effect {
  std::string id;  // the effect instance id
  std::string label;  // the effect's name
  std::string glyph;  // the symbol id (Fal-made status symbols, decision 0017 §5)
  EffectPolarity polarity{};  // how the stack colours an effect
  std::optional<double> remaining;  // seconds of game time left; absent for a constant effect
  bool operator==(const Effect&) const = default;
};

// The vastei plaque
struct Vastei {
  std::int64_t carried = 0;  // vastei carried
  std::optional<std::int64_t> gained;  // a recent gain shown beside the plaque
  bool operator==(const Vastei&) const = default;
};

// The banner shown on entering a place
struct PlaceBanner {
  std::string place;  // world db place.id
  std::string name;  // the place's name
  std::optional<std::string> region;  // the region's name
  bool first_visit = false;  // true on discovery
  bool operator==(const PlaceBanner&) const = default;
};

// The glyph for one input on one device
struct InputGlyph {
  InputDevice device{};  // the device a glyph belongs to
  std::string glyph;  // the glyph id in the symbol set (Skyrim's own, extracted at install, decision 0017 §5)
  bool operator==(const InputGlyph&) const = default;
};

// The activation prompt
struct Prompt {
  std::string verb;  // what activating does (Talk, Take, Open)
  std::string target;  // what it is done to
  std::vector<InputGlyph> inputs;  // the glyph per device
  bool operator==(const Prompt&) const = default;
};

// One line of the notice stack
struct Notice {
  std::string id;  // the notice id, so a view can fade it once
  NoticeKind kind{};  // what raised a notice
  std::string text;  // the line
  bool operator==(const Notice&) const = default;
};

// The whole HUD, sent on any change but the bars
struct HudState {
  bool visible = false;  // false while one of our views or a menu covers play
  std::vector<Bar> bars;  // One bar; its drawn length grows with max
  Sneak sneak;  // The sneak eye
  std::vector<Effect> effects;  // the effect stack, newest first
  Vastei vastei;  // The vastei plaque
  std::optional<PlaceBanner> banner;  // The banner shown on entering a place
  std::optional<Prompt> prompt;  // The activation prompt
  std::vector<Notice> notices;  // newest last
  bool operator==(const HudState&) const = default;
};

// The bars alone, the HUD's frequent update
struct HudBars {
  std::vector<Bar> bars;  // One bar; its drawn length grows with max
  bool operator==(const HudBars&) const = default;
};

// Where the player stands and faces, in the province
struct ChartPlayer {
  double x = 0;  // position in cell units
  double y = 0;  // position in cell units
  double heading = 0;  // degrees clockwise from north
  bool operator==(const ChartPlayer&) const = default;
};

// One exterior cell of the worldspace grid
struct CellKey {
  std::int64_t x = 0;  // cell grid x
  std::int64_t y = 0;  // cell grid y
  bool operator==(const CellKey&) const = default;
};

// A discovered place: its map marker, whose discovery has fired
struct ChartPlace {
  std::string id;  // the map marker reference's form id, 8 hex digits
  std::string name;  // the name lettered on the chart (the marker's name)
  std::string kind;  // the marker's glyph kind (settlement, ruin, lair, ...; core chart::marker_kind)
  double x = 0;  // position in cell units
  double y = 0;  // position in cell units
  bool operator==(const ChartPlace&) const = default;
};

// The HUD's minimap: the chart round the player
struct Minimap {
  std::optional<ChartPlayer> player;  // absent outside the province: the minimap hides
  std::vector<CellKey> revealed;  // the revealed cells within the minimap's reach (core chart::near)
  std::vector<ChartPlace> places;  // the discovered places within its reach
  bool operator==(const Minimap&) const = default;
};

// The minimap alone, sent when the player's cell, place or facing moves
struct HudMinimap {
  Minimap map;  // The HUD's minimap: the chart round the player
  bool operator==(const HudMinimap&) const = default;
};

// Where the chart is looking; kept by ArgoniaCore between openings
struct ChartView {
  double centre_x = 0;  // centre in cell units
  double centre_y = 0;  // centre in cell units
  double zoom = 0;  // scale factor, 1 the whole province
  bool operator==(const ChartView&) const = default;
};

// The open chart
struct ChartState {
  std::string worldspace;  // world db worldspace id
  std::string sketch;  // the sketch layer image id the view loads
  std::vector<CellKey> revealed;  // every cell the player has uncovered
  std::vector<ChartPlace> places;  // the discovered places only
  std::optional<ChartPlayer> player;  // absent outside the province (an interior, another worldspace)
  ChartView view;  // Where the chart is looking; kept by ArgoniaCore between openings
  bool operator==(const ChartState&) const = default;
};

// The chart was panned or zoomed
struct ChartPan {
  ChartView view;  // Where the chart is looking; kept by ArgoniaCore between openings
  bool operator==(const ChartPan&) const = default;
};

// One attribute's row of the sitting
struct SittingAttribute {
  AttributeId id{};  // one of the seven attributes (Morrowind's, without Luck)
  std::string name;  // the attribute's name as the sheet shows it
  std::int64_t value = 0;  // the attribute now, with this sitting's points
  std::int64_t bought = 0;  // points bought this sitting
  std::int64_t cap = 0;  // the most points one sitting may buy
  double cost = 0;  // the vastei the next point costs (cost formula, ArgoniaCore's)
  std::optional<SittingRefusal> refusal;  // why the next point cannot be bought; absent when it can
  bool operator==(const SittingAttribute&) const = default;
};

// A pool the sitting recomputes
struct SittingPool {
  double before = 0;  // the maximum when the sitting opened
  double after = 0;  // the maximum with this sitting's points
  bool operator==(const SittingPool&) const = default;
};

// The open sitting after each purchase
struct SittingState {
  std::int64_t level = 0;  // the level this sitting takes
  double vastei = 0;  // vastei carried, after this sitting's purchases
  std::int64_t pending_after = 0;  // pending levels left for later rests
  std::vector<SittingAttribute> attributes;  // the seven attributes, in the sheet's order
  SittingPool health;  // A pool the sitting recomputes
  std::optional<std::string> notice;  // one line about the last pick (a refusal), as ArgoniaCore words it
  bool operator==(const SittingState&) const = default;
};

// The player bought one point of an attribute
struct SittingBuy {
  AttributeId attribute{};  // one of the seven attributes (Morrowind's, without Luck)
  bool operator==(const SittingBuy&) const = default;
};

// The player rose from the sitting; unspent vastei carries over
struct SittingDone {
  bool operator==(const SittingDone&) const = default;
};

// A power or lesser power the player has
struct MagicPower {
  std::string id;  // the power's form id, 8 hex digits
  std::string name;  // the power's name
  bool readied = false;  // readied in the voice slot
  bool operator==(const MagicPower&) const = default;
};

// One spell the player knows
struct MagicSpell {
  std::string id;  // the spell's form id, 8 hex digits
  std::string name;  // the spell's name as the game has it (our restated name where mod_form gives one)
  std::int64_t cost = 0;  // magicka to cast, the engine's figure for the player now
  std::optional<std::int64_t> chance;  // the chance to cast, percent; absent: Skyrim has none
  bool left = false;  // readied in the left hand
  bool right = false;  // readied in the right hand
  bool operator==(const MagicSpell&) const = default;
};

// One school's heading and its spells, by name
struct MagicGroup {
  MagicSchool school{};  // one of Morrowind's six schools of magic
  std::string name;  // the heading as the player reads it
  std::vector<MagicSpell> spells;  // by name; empty when the player knows none of the school
  bool operator==(const MagicGroup&) const = default;
};

// An effect on the player now
struct MagicActive {
  std::string name;  // the effect's name
  std::optional<std::string> detail;  // its magnitude and time left, as ArgoniaCore words them
  bool operator==(const MagicActive&) const = default;
};

// The open magic pane
struct MagicState {
  std::vector<MagicPower> powers;  // by name
  std::vector<MagicGroup> groups;  // the six schools, always, in Morrowind's order
  std::vector<MagicActive> effects;  // the active effects shown in the game's UI, by name
  std::optional<std::string> notice;  // one line about the last pick (a refusal), as ArgoniaCore words it
  bool operator==(const MagicState&) const = default;
};

// The player readied a spell in a hand, or a power
struct MagicEquip {
  std::string spell;  // the spell's or power's form id, 8 hex digits
  Hand hand{};  // where a readied spell or power goes
  bool operator==(const MagicEquip&) const = default;
};

// The open System pane
struct SystemState {
  bool can_load = false;  // a save exists to load (the engine's Load entry is enabled)
  bool operator==(const SystemState&) const = default;
};

// The player picked an entry on the System pane
struct SystemPick {
  SystemAction action{};  // what the player picked on the System pane
  bool operator==(const SystemPick&) const = default;
};

// The open wait window
struct WaitState {
  WaitMode mode{};  // the engine's mode for the Sleep/Wait Menu
  std::string now;  // the time of day and date as the player reads it (ArgoniaCore words it; views never format game dates)
  std::int64_t hours = 0;  // the hours the window opens on
  std::int64_t max = 0;  // the most hours one wait may take (Dear Diary's config cap, the engine's)
  bool operator==(const WaitState&) const = default;
};

// The player chose to wait or sleep this many hours
struct WaitPick {
  std::int64_t hours = 0;  // hours, within the window's max
  bool operator==(const WaitPick&) const = default;
};

// The player closed a view (Escape, the pad's B, the close button)
struct ViewClose {
  ViewId view{};  // a view the player can close
  bool operator==(const ViewClose&) const = default;
};

